90.         this.abortController?.abort();
91.         this.abortController = new AbortController();
92.         const signal = this.abortController.signal;
93.         const formData = new FormData();
94.         try {
95.             const credential = await this.obtainCredential(useConditionalMediation, signal);
96.             const credentialJson = JSON.stringify(credential);
97.             formData.append(`${this.attrs.name}.CredentialJson`, credentialJson);
98.         } catch (error) {
