16. {
17.     <h3>Registered Logins</h3>
18.     <table class="table">
19.         <tbody>
20.             @foreach (var login in currentLogins)
21.             {
22.                 <tr>
23.                     <td>@login.ProviderDisplayName</td>
24.                     <td>
25.                         @if (showRemoveButton)
26.                         {
27.                             <form @formname="@($"remove-login-{login.LoginProvider}")" @onsubmit="OnSubmitAsync" method="post">
28.                                 <AntiforgeryToken />
29.                                 <div>
30.                                     <input type="hidden" name="@nameof(LoginProvider)" value="@login.LoginProvider" />
31.                                     <input type="hidden" name="@nameof(ProviderKey)" value="@login.ProviderKey" />
32.                                     <button type="submit" class="btn btn-primary" title="Remove this @login.ProviderDisplayName login from your account">Remove</button>
33.                                 </div>
34.                             </form>
35.                         }
36.                         else
37.                         {
38.                             @: &nbsp;
39.                         }
40.                     </td>
41.                 </tr>
42.             }
43.         </tbody>
44.     </table>
45. }
46. @if (otherLogins?.Count > 0)
47. {
48.     <h4>Add another service to log in.</h4>
49.     <hr />
50.     <form class="form-horizontal" action="Account/Manage/LinkExternalLogin" method="post">
51.         <AntiforgeryToken />
52.         <div>
53.             <p>
54.                 @foreach (var provider in otherLogins)
55.                 {
56.                     <button type="submit" class="btn btn-primary" name="Provider" value="@provider.Name" title="Log in using your @provider.DisplayName account">
57.                         @provider.DisplayName
58.                     </button>
59.                 }
60.             </p>
61.         </div>
62.     </form>
63. }
