65. @code {
66.     public const string LinkLoginCallbackAction = "LinkLoginCallback";
67. 
68.     private ApplicationUser? user;
69.     private IList<UserLoginInfo>? currentLogins;
70.     private IList<AuthenticationScheme>? otherLogins;
71.     private bool showRemoveButton;
72. 
73.     [CascadingParameter]
74.     private HttpContext HttpContext { get; set; } = default!;
75. 
76.     [SupplyParameterFromForm]
77.     private string? LoginProvider { get; set; }
78. 
79.     [SupplyParameterFromForm]
80.     private string? ProviderKey { get; set; }
81. 
82.     [SupplyParameterFromQuery]
83.     private string? Action { get; set; }
84. 
85.     protected override async Task OnInitializedAsync()
86.     {
87.         user = await UserManager.GetUserAsync(HttpContext.User);
88.         if (user is null)
89.         {
90.             RedirectManager.RedirectToInvalidUser(UserManager, HttpContext);
91.             return;
92.         }
93. 
94.         currentLogins = await UserManager.GetLoginsAsync(user);
95.         otherLogins = (await SignInManager.GetExternalAuthenticationSchemesAsync())
96.             .Where(auth => currentLogins.All(ul => auth.Name != ul.LoginProvider))
97.             .ToList();
98. 
99.         string? passwordHash = null;
100.         if (UserStore is IUserPasswordStore<ApplicationUser> userPasswordStore)
101.         {
102.             passwordHash = await userPasswordStore.GetPasswordHashAsync(user, HttpContext.RequestAborted);
103.         }
104. 
105.         showRemoveButton = passwordHash is not null || currentLogins.Count > 1;
106. 
107.         if (HttpMethods.IsGet(HttpContext.Request.Method) && Action == LinkLoginCallbackAction)
108.         {
109.             await OnGetLinkLoginCallbackAsync();
110.         }
111.     }
112. 
113.     private async Task OnSubmitAsync()
114.     {
115.         if (user is null)
116.         {
117.             RedirectManager.RedirectToInvalidUser(UserManager, HttpContext);
118.             return;
119.         }
120. 
121.         var result = await UserManager.RemoveLoginAsync(user, LoginProvider!, ProviderKey!);
122.         if (!result.Succeeded)
123.         {
124.             RedirectManager.RedirectToCurrentPageWithStatus("Error: The external login was not removed.", HttpContext);
125.         }
126.         else
127.         {
128.             await SignInManager.RefreshSignInAsync(user);
129.             RedirectManager.RedirectToCurrentPageWithStatus("The external login was removed.", HttpContext);
130.         }
131.     }
132. 
133.     private async Task OnGetLinkLoginCallbackAsync()
134.     {
135.         if (user is null)
136.         {
137.             RedirectManager.RedirectToInvalidUser(UserManager, HttpContext);
138.             return;
139.         }
140. 
141.         var userId = await UserManager.GetUserIdAsync(user);
142.         var info = await SignInManager.GetExternalLoginInfoAsync(userId);
143.         if (info is null)
144.         {
145.             RedirectManager.RedirectToCurrentPageWithStatus("Error: Could not load external login info.", HttpContext);
146.             return;
147.         }
148. 
149.         var result = await UserManager.AddLoginAsync(user, info);
150.         if (result.Succeeded)
151.         {
152.             // Clear the existing external cookie to ensure a clean login process
153.             await HttpContext.SignOutAsync(IdentityConstants.ExternalScheme);
154. 
155.             RedirectManager.RedirectToCurrentPageWithStatus("The external login was added.", HttpContext);
156.         }
157.         else
158.         {
159.             RedirectManager.RedirectToCurrentPageWithStatus("Error: The external login was not added. External logins can only be associated with one account.", HttpContext);
160.         }
161.     }
162. }
