@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private bool isSearching;
    private bool searchPerformed;
    private Shipment? trackedShipment;
    private List<Shipment>? myShipments;

    protected override async Task OnInitializedAsync()
    {
        var authState = await AuthStateProvider.GetAuthenticationStateAsync();
        var email = authState.User.FindFirst(System.Security.Claims.ClaimTypes.Email)?.Value
                    ?? authState.User.FindFirst("email")?.Value
                    ?? authState.User.Identity?.Name;

        if (!string.IsNullOrEmpty(email))
        {
            myShipments = await ShipmentService.GetShipmentsByCustomerAsync(email);
        }
        else
        {
            myShipments = [];
        }
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isSearching = true;
        searchPerformed = false;
        trackedShipment = null;

        trackedShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
        searchedNumber = trackingNumber.Trim();
        searchPerformed = true;
        isSearching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await TrackShipment();
        }
    }

    private void ShowShipment(Shipment shipment)
    {
        trackedShipment = shipment;
        trackingNumber = shipment.TrackingNumber;
        searchedNumber = shipment.TrackingNumber;
        searchPerformed = true;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };
}

