 @page "/dispatcher"
 @using ShipmentTracker.Client.Models
 @attribute [Authorize(Roles = "Dispatcher")]
 @inject IShipmentService ShipmentService

 <PageTitle>Dispatcher Dashboard</PageTitle>

 <h1>Dispatcher Dashboard</h1>

 <div class="mb-3">
     <label class="form-label fw-bold">Filter by Status:</label>
     <select class="form-select w-auto d-inline-block" @bind="statusFilter">
         <option value="">All Statuses</option>
         @foreach (var status in Enum.GetValues<ShipmentStatus>())
         {
             <option value="@status">@status</option>
         }
     </select>
 </div>

 @if (shipments is null)
 {
     <p><em>Loading shipments...</em></p>
 }
 else if (!FilteredShipments.Any())
 {
     <p>No shipments found.</p>
 }
 else
 {
     <div class="table-responsive">
         <table class="table table-striped table-hover">
             <thead class="table-dark">
                 <tr>
                     <th>Tracking #</th>
                     <th>Origin</th>
                     <th>Destination</th>
                     <th>Recipient</th>
                     <th>Status</th>
                     <th>Shipped</th>
                     <th>Est. Delivery</th>
                     <th>Actions</th>
                 </tr>
             </thead>
             <tbody>
                 @foreach (var s in FilteredShipments)
                 {
                     <tr>
                         <td><strong>@s.TrackingNumber</strong></td>
                         <td>@s.Origin</td>
                         <td>@s.Destination</td>
                         <td>@s.RecipientName</td>
                         <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                         <td>@s.ShippedDate.ToString("MMM dd, yyyy")</td>
                         <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                         <td>
                             <select class="form-select form-select-sm"
                                     value="@s.Status"
                                     @onchange="e => UpdateStatus(s, e)">
                                 @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                 {
                                     <option value="@status" selected="@(s.Status == status)">@status</option>
                                 }
                             </select>
                         </td>
                     </tr>
                 }
             </tbody>
         </table>
     </div>
 }

 @code {
     private List<Shipment>? shipments;
     private string statusFilter = "";

     private IEnumerable<Shipment> FilteredShipments =>
         string.IsNullOrEmpty(statusFilter)
             ? shipments ?? []
             : shipments?.Where(s => s.Status.ToString() == statusFilter) ?? [];

     protected override async Task OnInitializedAsync()
     {
         shipments = await ShipmentService.GetAllShipmentsAsync();
     }

     private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
     {
         if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
         {
             await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
             shipment.Status = newStatus;
             if (newStatus == ShipmentStatus.Delivered)
             {
                 shipment.ActualDelivery = DateTime.UtcNow;
             }
         }
     }

     private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
     {
         ShipmentStatus.Pending => "bg-secondary",
         ShipmentStatus.PickedUp => "bg-info",
         ShipmentStatus.InTransit => "bg-primary",
         ShipmentStatus.OutForDelivery => "bg-warning text-dark",
         ShipmentStatus.Delivered => "bg-success",
         ShipmentStatus.Exception => "bg-danger",
         _ => "bg-secondary"
     };
 }

