                 EstimatedDelivery = now.AddDays(4),
                 RecipientName = "Henry Brown",
                 CustomerEmail = "bob@example.com"
             }
         };

         db.Shipments.AddRange(shipments);
         await db.SaveChangesAsync();
     }
 }

